function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var HT=['Mild','Medium','Caliente','Fuego','Loco'];var HX=['You owe him one thing, the transcript. Send it.','He asked which tools you use and got the cosmology.','The one-line challenge was right and pointed at the wrong person.','A second user who nearly built your tool is a design partner.','Do not build him a tenant.'];
function kitTake(l){var p='';for(var j=1;j<=5;j++)p+='<b'+(j<=l?' class="on"':'')+'></b>';return '<div class="take"><span class="heat"><span class="heat-pips" aria-hidden="true">'+p+'</span>'+HT[l-1]+'</span><p class="take-text">'+kEsc(HX[l-1])+'</p></div>'}
function kitTakes(host,ls){var w=document.createElement('div');w.className='takes';w.innerHTML=ls.map(kitTake).join('');host.appendChild(w);return w}
kitTakes(kSlot(),[1,2,3,4,5]);
